/** Who the account is, as the player sees it on their profile. */
export interface ProfileSaveExtract {
  /** The name the player chose, or null when the save has none. */
  userName: string | null
  /** The avatar picked, by the game's avatar number. */
  avatarId: number | null
  /** Whether the account is in a guild. */
  inGuild: boolean | null
  /** The newest guild season the account has seen. */
  lastGuildSeason: number | null
  warnings: string[]
}
